  const button=(label,act,attrs='')=>'<button type="button" data-w-act="'+act+'" '+attrs+'>'+esc(label)+'</button>';
  const input=(label,path,value,type='text',attrs='')=>'<label class="wp-field"><span>'+esc(label)+'</span><input type="'+type+'" data-w-path="'+esc(path)+'" value="'+esc(value??'')+'" '+attrs+(type==='number'?' min="0" step="any" inputmode="decimal" placeholder="—"':'')+'></label>';
  const select=(label,path,value,values)=>'<label class="wp-field"><span>'+esc(label)+'</span><select data-w-path="'+esc(path)+'">'+values.map(x=>'<option value="'+esc(x)+'"'+(value===x?' selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label>';
  const target=(round,loadMode='total')=>({id:uid(),round,reps:null,weight:null,unit:'lb',seconds:null,loadMode,repsMode:'total'});
