    const steps=W.guidanceSteps(c.v.plan),step=steps[state.stepIndex],entry=c.v.plan.exercises.find(e=>e.id===step.exerciseId),g=c.v.plan.groups.find(g=>g.id===step.groupId),side=entry.side&&entry.side!=='none'?' · '+entry.side.toUpperCase():'';
